import{_ as l,a0 as i,w as d,s as r,ao as o,I as t,x as s,a1 as p,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"編寫一個簡單的遊戲來學習 Python | LCTT x X-CMD","titleTemplate":false,"description":"編寫一個簡單的遊戲來學習 Python | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"編寫一個簡單的遊戲來學習 Python | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"編寫一個簡單的遊戲來學習 Python | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20201228 Learn Python by coding a simple game","title":"編寫一個簡單的遊戲來學習 Python","tag":"202101","desc":""},"relativePath":"202101/20201228 Learn Python by coding a simple game.md","filePath":"[post].md"}'),h={name:"202101/20201228 Learn Python by coding a simple game.md"};function u(m,n,g,c,y,T){const a=i("Link");return d(),r("div",null,[n[18]||(n[18]=o('<h1 id="編寫一個簡單的遊戲來學習-python" tabindex="-1">編寫一個簡單的遊戲來學習 Python <a class="header-anchor" href="#編寫一個簡單的遊戲來學習-python" aria-label="Permalink to “編寫一個簡單的遊戲來學習 Python”">​</a></h1><blockquote><p>通過編寫一個“猜數字”遊戲來探索 Python（和其他編程語言）。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202101/01/105156uwwgx3tw2otntoow.jpg" alt=""></p><p>在這個系列中，我們要用不同的編程語言編寫相同的應用，以比較各種語言是如何工作的，並説明使用標準測試程序是學習新編程好方法。</p><p>當你學習一門新的編程語言時，關注它們的共同點是件好事。變量、表達式和語句是大多數編程語言的基礎。一旦你理解了這些概念，你就可以開始弄清楚其餘的東西。</p><p>因為編程語言有許多相似之處，一旦你知道一種語言，你通常可以通過觀察它與你所知道的語言的不同之處來學習另一種語言的基礎知識。使用你用其他語言編寫的標準測試程序，可以讓你專注於語言，而不是程序的邏輯。</p><p>為了證明這點，我們正在測試如何用多種語言編寫一個“猜數字”程序。計算機選擇一個 1 到 100 之間的數字，然後讓你猜。程序循環，直到你猜出正確答案。</p><p>“猜數字”程序練習了編程語言的幾個概念：</p><ul><li>變量</li><li>輸入</li><li>輸出</li><li>條件判斷</li><li>循環</li></ul><p>這是一個很好的學習新編程語言的實踐實驗。</p><h3 id="用-python-猜數字" tabindex="-1">用 Python 猜數字 <a class="header-anchor" href="#用-python-猜數字" aria-label="Permalink to “用 Python 猜數字”">​</a></h3>',11)),t("p",null,[n[1]||(n[1]=s("用 ",-1)),p(a,{href:"https://docs.python.org/3/faq/general.html#general-information"},{default:e(()=>[...n[0]||(n[0]=[s("Python 軟件基金會",-1)])]),_:1}),n[2]||(n[2]=s("的話來説。“Python 是一種解釋性的、交互式的、面向對象的程序設計語言，它包含了模組、異常、動態類型、非常高層的動態數據類型和類。”它是一種很好的通用編程語言，從簡單的腳本到複雜的 GUI 應用都很適用。",-1))]),n[19]||(n[19]=o(`<p>你可以通過編寫一個版本的“猜數字”遊戲來探索 Python。這是我的實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random as randomlib</span></span>
<span class="line"><span>random = randomlib.randint(1, 100)</span></span>
<span class="line"><span>print(&quot;Guess a number between 1 and 100&quot;)</span></span>
<span class="line"><span>while True:</span></span>
<span class="line"><span>    guess = int(input())</span></span>
<span class="line"><span>    if guess &amp;lt; random:</span></span>
<span class="line"><span>        print(&quot;Too low&quot;)</span></span>
<span class="line"><span>    elif guess &amp;gt; random:</span></span>
<span class="line"><span>        print(&quot;Too high&quot;)</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;That&#39;s right!&quot;)</span></span>
<span class="line"><span>        break</span></span></code></pre></div><p>要給一個變量賦值，請列出變量的名稱，然後是 <code>=</code> 號。例如，語句 <code>random = 0</code> 給 <code>random</code> 變量分配了一個零值。</p><p>腳本的第一行就導入了 <code>random</code> 模組。由於本系列中的所有程序都使用 <code>random</code> 作為變量的名稱，你可以使用 <code>import random as randomlib</code> 以別名導入它，以避免命名衝突。</p><p>很少有函數被內置到 Python 中，大多數函數必須從標準庫中顯式導入。<code>random</code> 標準庫模組有生成各種隨機值的功能。</p><p>腳本的第二行讀取函數 <code>randint()</code> 的結果，並將其賦值給名為 <code>random</code> 的變量。函數需要兩個參數：一個最小值和一個最大值。在本例中，範圍是 <code>1</code> 到 <code>100</code>，以使遊戲具有足夠的挑戰性。</p><p>你可以使用 <code>input()</code> 函數提示用户輸入一個值。如果你寫 <code>guess = int(input())</code>，Python 會等待用户輸入一些文本，將其轉換為一個整數，然後將值存儲在 <code>guess</code> 變量中。</p><p>Python 支持條件表達式和循環等流程控制。在“猜數字”遊戲中，只要 <code>guess</code> 中的值不等於 <code>random</code>，Python 就會繼續循環。</p><p>如果猜測值小於隨機數，Python 會打印 <code>Too low</code>，如果猜測值大於這個數字，Python 會打印 <code>Too high</code>。</p><h3 id="示例輸出" tabindex="-1">示例輸出 <a class="header-anchor" href="#示例輸出" aria-label="Permalink to “示例輸出”">​</a></h3><p>現在你已經寫好了 Python 程序，運行它來玩“猜數字”遊戲。每次運行程序，Python 都會隨機選取一個不同的數字。為了完成這個遊戲，你需要猜測，直到找到正確的數字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python guess.py</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span> 50</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 25</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 12</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 7</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span> 3</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span> 5</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span> 6</span></span>
<span class="line"><span>That&#39;s right!</span></span></code></pre></div><p>在學習一門新的編程語言時，這個“猜數字”遊戲是一個很好的入門程序，因為它以一種相當直接的方式練習了幾個常見的編程概念。通過在不同的編程語言中實現這個簡單的遊戲，你可以展示不同編程語言的一些核心概念，並比較每種語言的細節。</p><p>你有喜歡的編程語言嗎？你會如何編寫“猜數字”遊戲？請關注本系列文章，看看你可能感興趣的其他編程語言的例子吧！</p><hr>`,15)),t("p",null,[n[4]||(n[4]=s("via: ",-1)),p(a,{href:"https://opensource.com/article/20/12/learn-python"},{default:e(()=>[...n[3]||(n[3]=[s("https://opensource.com/article/20/12/learn-python",-1)])]),_:1})]),t("p",null,[n[9]||(n[9]=s("作者：",-1)),p(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...n[5]||(n[5]=[s("Moshe Zadka",-1)])]),_:1}),n[10]||(n[10]=s(" 選題：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...n[6]||(n[6]=[s("lujun9972",-1)])]),_:1}),n[11]||(n[11]=s(" 譯者：",-1)),p(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[7]||(n[7]=[s("geekpi",-1)])]),_:1}),n[12]||(n[12]=s(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[8]||(n[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[n[15]||(n[15]=s("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[13]||(n[13]=[s("LCTT",-1)])]),_:1}),n[16]||(n[16]=s(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...n[14]||(n[14]=[s("Linux中國",-1)])]),_:1}),n[17]||(n[17]=s(" 榮譽推出",-1))])])}const k=l(h,[["render",u]]);export{P as __pageData,k as default};
